1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eef0f3;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 300px;
20	    padding: 16px;
21	    background: #1f2329;
22	    border-radius: 16px;
23	    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
24	  }
25	  .display {
26	    height: 72px;
27	    margin-bottom: 12px;
28	    padding: 0 12px;
29	    display: flex;
30	    align-items: center;
31	    justify-content: flex-end;
32	    background: #111418;
33	    color: #fff;
34	    font-size: 40px;
35	    border-radius: 10px;
36	    overflow: hidden;
37	    white-space: nowrap;
38	  }
39	  .keys {
40	    display: grid;
41	    grid-template-columns: repeat(4, 1fr);
42	    gap: 8px;
43	  }
44	  button {
45	    height: 56px;
46	    border: 0;
47	    border-radius: 10px;
48	    background: #3a3f47;
49	    color: #fff;
50	    font-size: 22px;
51	    cursor: pointer;
52	  }
53	  button:active { filter: brightness(1.3); }
54	  button.op { background: #f0a030; }
55	  button.clear { background: #a5a5a5; color: #111; }
56	  button.equals { background: #3c8cf0; }
57	  button.wide { grid-column: span 2; }
58	</style>
59	</head>
60	<body>
61	<div class="calc">
62	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" aria-live="polite">0</div>
63	  <div class="keys">
64	    <button class="clear wide" data-testid="key-lparen" aria-label="open group">(</button>
65	    <button class="clear wide" data-testid="key-rparen" aria-label="close group">)</button>
66	
67	    <button class="clear wide" data-testid="key-clear">AC</button>
68	    <button class="clear" data-testid="key-sign" aria-label="change sign">±</button>
69	    <button class="op" data-testid="key-div" aria-label="divide">÷</button>
70	
71	    <button data-testid="key-7">7</button>
72	    <button data-testid="key-8">8</button>
73	    <button data-testid="key-9">9</button>
74	    <button class="op" data-testid="key-mul" aria-label="multiply">×</button>
75	
76	    <button data-testid="key-4">4</button>
77	    <button data-testid="key-5">5</button>
78	    <button data-testid="key-6">6</button>
79	    <button class="op" data-testid="key-sub" aria-label="subtract">−</button>
80	
81	    <button data-testid="key-1">1</button>
82	    <button data-testid="key-2">2</button>
83	    <button data-testid="key-3">3</button>
84	    <button class="op" data-testid="key-add" aria-label="add">+</button>
85	
86	    <button class="wide" data-testid="key-0">0</button>
87	    <button data-testid="key-dot" aria-label="decimal point">.</button>
88	    <button class="equals" data-testid="key-equals" aria-label="equals">=</button>
89	  </div>
90	</div>
91	<script>
92	(function () {
93	  var display = document.querySelector('[data-testid="calc-display"]');
94	
95	  // entry: string being typed, or null when no entry is in progress.
96	  // value: the number currently shown when not typing (result or stored operand).
97	  // derived: true when entry came from ± on a computed number rather than typing;
98	  // it is shown formatted, and the next digit starts a new entry.
99	
100	  // groups: stack of the outer { stored, op } saved by each open "(".
101	  var state;
102	
103	  // [REQ-001] [REQ-004] [REQ-005]
104	  function reset() {
105	    state = { entry: null, value: 0, stored: null, op: null, error: false, derived: false, groups: [] };
106	  }
107	
108	  // [REQ-001]
109	  function compute(a, op, b) {
110	    var r;
111	    if (op === 'add') r = a + b;
112	    else if (op === 'sub') r = a - b;
113	    else if (op === 'mul') r = a * b;
114	    else if (op === 'div') r = a / b;
115	    // [REQ-003] Division by zero (or any non-finite result) becomes the error state.
116	    // The result is never rounded here: rounding is presentation only.
117	    if (!isFinite(r)) return NaN;
118	    return r;
119	  }
120	
121	  // [REQ-003]
122	  // Presentation only: at most 10 significant digits, no trailing zeros, no
123	  // thousands separators, exponential only for |n| >= 1e10 or |n| < 1e-9.
124	  function formatNumber(n) {
125	    if (n === 0) return '0';
126	    var r = Number(n.toPrecision(10));
127	    var abs = Math.abs(r);
128	    if (abs >= 1e10 || abs < 1e-9) {
129	      return r.toExponential(9).replace(/\.?0+e/, 'e');
130	    }
131	    var exp = parseInt(r.toExponential().split('e')[1], 10);
132	    var s = r.toFixed(Math.max(0, 9 - exp));
133	    return s.indexOf('.') === -1 ? s : s.replace(/\.?0+$/, '');
134	  }
135	
136	  // [REQ-001] [REQ-003]
137	  function render() {
138	    display.setAttribute('data-error', state.error ? 'true' : 'false');
139	    if (state.error) {
140	      display.textContent = 'Error';
141	      display.setAttribute('data-value', String(NaN));
142	      return;
143	    }
144	    if (state.entry !== null) {
145	      display.textContent = state.derived ? formatNumber(Number(state.entry)) : state.entry;
146	      display.setAttribute('data-value', String(Number(state.entry)));
147	    } else {
148	      display.textContent = formatNumber(state.value);
149	      display.setAttribute('data-value', String(state.value));
150	    }
151	  }
152	
153	  // [REQ-001]
154	  function inputDigit(d) {
155	    if (state.derived) { state.entry = null; state.derived = false; }
156	    if (state.entry === null || state.entry === '0') state.entry = d;
157	    else state.entry += d;
158	  }
159	
160	  // [REQ-001]
161	  function inputDot() {
162	    if (state.derived) { state.entry = null; state.derived = false; }
163	    if (state.entry === null) state.entry = '0.';
164	    else if (state.entry.indexOf('.') === -1) state.entry += '.';
165	  }
166	
167	  // [REQ-004] [REQ-006]
168	  // ± acts on the current entry. With no entry in progress, the number on
169	  // the display becomes the entry, so it can still feed the pending operation.
170	  function inputSign() {
171	    if (state.entry === null) { state.entry = String(state.value); state.derived = true; }
172	    state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
173	  }
174	
175	  // [REQ-001] [REQ-002]
176	  // Immediate execution: an operator key first finishes the waiting operation,
177	  // strictly left to right, with no precedence, so the display always shows a
178	  // real running result. 2 + 3 × 4 = 20.
179	  function inputOperator(op) {
180	    if (state.error) return;
181	    if (state.entry !== null) {
182	      var n = Number(state.entry);
183	      state.entry = null;
184	      state.derived = false;
185	      if (state.op !== null && state.stored !== null) {
186	        state.value = compute(state.stored, state.op, n);
187	        if (isNaN(state.value)) { state.error = true; return; }
188	      } else {
189	        state.value = n;
190	      }
191	    }
192	    state.stored = state.value;
193	    state.op = op;
194	  }
195	
196	  // [REQ-005]
197	  // "(" starts a group only where a new number could start. It saves the waiting
198	  // operation and begins a fresh calculation inside the group.
199	  function inputOpenGroup() {
200	    if (state.entry !== null) return;
201	    state.groups.push({ stored: state.stored, op: state.op });
202	    state.stored = null;
203	    state.op = null;
204	  }
205	
206	  // [REQ-005]
207	  // ")" finishes the calculation inside the group, left to right, and hands its
208	  // result back as the entry for the saved outer operation.
209	  function inputCloseGroup() {
210	    if (state.groups.length === 0 || state.entry === null) return;
211	    var n = Number(state.entry);
212	    if (state.op !== null && state.stored !== null) {
213	      n = compute(state.stored, state.op, n);
214	      if (isNaN(n)) { state.error = true; return; }
215	    }
216	    var outer = state.groups.pop();
217	    state.stored = outer.stored;
218	    state.op = outer.op;
219	    state.value = n;
220	    state.entry = String(n);
221	    state.derived = true;
222	  }
223	
224	  // [REQ-001] [REQ-005]
225	  function inputEquals() {
226	    // Groups still open are closed first.
227	    while (!state.error && state.groups.length > 0 && state.entry !== null) inputCloseGroup();
228	    if (state.error || state.op === null || state.entry === null) return;
229	    var result = compute(state.stored, state.op, Number(state.entry));
230	    state.entry = null;
231	    state.derived = false;
232	    state.op = null;
233	    state.stored = null;
234	    if (isNaN(result)) { state.error = true; return; }
235	    state.value = result;
236	  }
237	
238	  // [REQ-001] [REQ-003] [REQ-004] [REQ-005] [REQ-006] The % key was removed.
239	  function press(key) {
240	    // In the error state every key except clear is ignored.
241	    if (state.error && key !== 'clear') return;
242	    if (/^[0-9]$/.test(key)) inputDigit(key);
243	    else if (key === 'dot') inputDot();
244	    else if (key === 'sign') inputSign();
245	    else if (key === 'add' || key === 'sub' || key === 'mul' || key === 'div') inputOperator(key);
246	    else if (key === 'lparen') inputOpenGroup();
247	    else if (key === 'rparen') inputCloseGroup();
248	    else if (key === 'equals') inputEquals();
249	    else if (key === 'clear') reset();
250	    render();
251	  }
252	
253	  document.querySelector('.keys').addEventListener('click', function (e) {
254	    var btn = e.target.closest('button[data-testid^="key-"]');
255	    if (btn) press(btn.getAttribute('data-testid').slice(4));
256	  });
257	
258	  var keyMap = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul',
259	    '/': 'div', '(': 'lparen', ')': 'rparen', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
260	  document.addEventListener('keydown', function (e) {
261	    if (e.metaKey || e.ctrlKey || e.altKey) return;
262	    var key = /^[0-9]$/.test(e.key) ? e.key : keyMap[e.key];
263	    if (key) {
264	      e.preventDefault();
265	      press(key);
266	    }
267	  });
268	
269	  reset();
270	  render();
271	})();
272	</script>
273	</body>
274	</html>
