var display = document.querySelector('[data-testid="calc-display"]');
var tape = document.querySelector('[data-testid="calc-tape"]');

// entry: string being typed, or null when no entry is in progress.
// value: the number currently shown when not typing (result or stored operand).
// derived: true when entry came from ± on a computed number rather than typing;
// it is shown formatted, and the next digit starts a new entry.

// groups: stack of the outer { stored, op, expr } saved by each open "(".
// expr: tokens of the expression written so far at the current group level.
// entryExpr: how the entry reads in the expression when it is a closed group.
var state;

var opSymbols = { add: '+', sub: '−', mul: '×', div: '÷' };

// [REQ-001] [REQ-004] [REQ-005] [REQ-007]
function reset() {
  state = { entry: null, value: 0, stored: null, op: null, error: false, derived: false, groups: [],
    expr: [], entryExpr: null };
}

// [REQ-007]
// How the current operand reads in the tape expression.
function operandText() {
  if (state.entry === null) return formatNumber(state.value);
  if (state.entryExpr !== null) return state.entryExpr;
  if (state.derived) return formatNumber(Number(state.entry));
  return state.entry.replace(/\.$/, '');
}

// [REQ-007]
// Newest row first. The tape is not part of state, so AC keeps it.
function addTapeRow(expr, result) {
  var row = document.createElement('div');
  row.className = 'tape-row';
  row.setAttribute('data-testid', 'tape-row');
  var e = document.createElement('div');
  e.className = 'tape-expr';
  e.setAttribute('data-testid', 'tape-expr');
  e.textContent = expr;
  var r = document.createElement('div');
  r.className = 'tape-result';
  r.setAttribute('data-testid', 'tape-result');
  r.setAttribute('data-value', String(result));
  r.textContent = formatNumber(result);
  row.appendChild(e);
  row.appendChild(r);
  tape.insertBefore(row, tape.firstChild);
}

